### function update(dt) 
 function update(dt){if(!started)return;elapsed+=dt;if(phase==='end')return;if(phase==='goal'){phaseTimer-=dt;if(phaseTimer<=0){phase='play';ui.toast.classList.remove('show');resetPositions();updateHUD();}return;}updateGlue(dt);timeLeft-=dt;if(timeLeft<=0){timeLeft=0;phase='end';ui.end.classList.add('show');document.getElementById('finalHome').textContent=String(score[0]).padStart(2,'0');document.getElementById('finalAway').textContent=String(score[1]).padStart(2,'0');document.getElementById('result').textContent=score[0]>score[1]?'VICTORY':score[0]<score[1]?'DEFEAT':'DRAW';document.getElementById('result').style.color=score[0]>=score[1]?cyan:coral;updateHUD();return;}
powerTimer-=dt;if(powerTimer<=0&&!powerOrb&&!powerEffect){spawnPower();powerTimer=12;}if(powerEffect){powerEffect.time-=dt;if(powerEffect.time<=0){powerEffect=null;players.forEach(p=>{p.boost=0;p.freeze=0;});}}if(powerOrb)powerOrb.phase+=dt*3;
