function aiMove(p,dt){if(p.freeze>0)return{x:0,y:0};const teamPlayers=players.filter(q=>q.team===p.team),mates=teamPlayers.filter(q=>q!==p),mate=mates[0],dir=p.team===0?1:-1,cy=field.y+field.h*.5,ownGoalX=p.team===0?field.x:field.x+field.w,oppGoalX=p.team===0?field.x+field.w:field.x;let nearest=players[0],nearestD=Infinity;for(const q of players){const d=hypot(ball.x-q.x,ball.y-q.y);if(d<nearestD){nearest=q;nearestD=d;}}let state=ball.glued?`${ball.glued.team===p.team?'team':'opponent'}-possession':nearestD<p.r+ball.r+23?`${nearest.team===p.team?'team':'opponent'}-possession`:ball.lastTouchTeam===undefined?'free-ball':`${ball.lastTouchTeam===p.team?'team':'opponent'}-possession`;const chaser=teamPlayers.reduce((a,b)=>hypot(a.x-ball.x,a.y-ball.y)<hypot(b.x-ball.x,b.y-ball.y)?a:b);let tx,ty;if(state==='free-ball'){if(chaser===p){tx=ball.x+ball.vx*.12;ty=ball.y+ball.vy*.12;}else if(p.role==='striker'){tx=clamp(ball.x+dir*field.w*.13,field.x+field.w*.12,field.x+field.w*.88);ty=cy+(ball.y-cy)*.38;}else{tx=ownGoalX+dir*field.w*.2;ty=cy+(ball.y-cy)*.5;}}else if(state==='team-possession'){if(p===ball.glued||nearest===p){tx=ball.x+dir*(p.r+ball.r+14);ty=ball.y;}else if(p.role==='striker'){tx=clamp(ball.x+dir*field.w*.19,field.x+field.w*.15,field.x+field.w*.9);ty=cy+(ball.y-cy)*.32;}else{tx=clamp(ball.x-dir*field.w*.16,field.x+field.w*.08,field.x+field.w*.82);ty=cy+(ball.y-cy)*.65;}}else{const pressing=teamPress&&p.team===0?chaser===p:chaser===p;if(pressing){tx=ball.x+ball.vx*.1;ty=ball.y+ball.vy*.1;}else if(p.role==='defender'){tx=ownGoalX+dir*field.w*.21;ty=cy+(ball.y-cy)*.38;}else{tx=clamp(ball.x+dir*field.w*.12,field.x+field.w*.12,field.x+field.w*.88);ty=cy+(ball.y-cy)*.55;}}if(p.team===0&&strategy==='attack'){tx=Math.max(tx,field.x+field.w*(p.role==='striker'?.66:.43));}if(p.team===0&&strategy==='defend'){tx=Math.min(tx,field.x+field.w*(p.role==='striker'?.68:.34));}if(p.team===0&&teamPress&&state==='opponent-possession'&&nearestD<field.w*.48){tx=ball.x+ball.vx*.08;ty=ball.y+ball.vy*.08;}tx=clamp(tx,field.x+p.r,field.x+field.w-p.r);ty=clamp(ty,field.y+p.r,field.y+field.h-p.r);const dx=tx-p.x,dy=ty-p.y,d=hypot(dx,dy)||1;if(d>p.r*.8&&d>65&&p.dashCd<=0&&Math.random()<dt*(.48*p.aggression))dash(p);if(p.pesi&&!p.human){p.faceX=1;p.faceY=clamp((ty-p.y)/(hypot(dx,dy)||1),-.35,.35);}else if(d>4){p.faceX=dx/d;p.faceY=dy/d;}return{x:dx/d,y:dy/d};}
function movePlayer(p,ax,ay,dt){if(p.freeze>0){p.freeze=Math.max(0,p.freeze-dt);ax=ay=0;}const boost=p.boost>0?1.32:1,speed=(p.baseSpeed||(p.human?210:184))*boost;const l=hypot(ax,ay);if(l>1){ax/=l;ay/=l;}if(l>.1){p.faceX=ax;p.faceY=ay;}const accel=p.dash>0?0:1000;p.vx+=ax*accel*dt;p.vy+=ay*accel*dt;const max=speed+(p.dash>0?310:0),v=hypot(p.vx,p.vy);if(v>max){p.vx*=max/v;p.vy*=max/v;}const drag=Math.pow(p.dash>0?.992:.84,dt*60);p.vx*=drag;p.vy*=drag;p.x+=p.vx*dt;p.y+=p.vy*dt;p.dash=Math.max(0,p.dash-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.kickFlash=Math.max(0,p.kickFlash-dt);p.boost=Math.max(0,p.boost-dt);p.kickCd=Math.max(0,p.kickCd-dt);p.x=clamp(p.x,field.x+p.r,field.x+field.w-p.r);p.y=clamp(p.y,field.y+p.r,field.y+field.h-p.r);}
